    title: "がっこうのひととなかよし",
    subtitle: "生活 小1",
    goal: "がっこうにいるひとのしごとをしり、あいさつやききかたをみにつける。",
    points: ["せんせい、しょくいん、うえのがくねんのひとにあいさつする。","こまったときに、だれにきくかをしる。","ありがとうをことばでつたえる。"],
    mistakes: ["だれのしごとかをたしかめずにきめる。"],
